/************************* Begin ext/misc/windirent.h ******************/
/*
** 2025-06-05
**
** The author disclaims copyright to this source code.  In place of
** a legal notice, here is a blessing:
**
**    May you do good and not evil.
**    May you find forgiveness for yourself and forgive others.
**    May you share freely, never taking more than you give.
**
*************************************************************************
**
** An implementation of opendir(), readdir(), and closedir() for Windows,
** based on the __find_first_file(), __find_next_file(), and __find_close() APIs
** of Win32.
**
** #include this file inside any C-code module that needs to use
** opendir()/readdir()/closedir().  This file is a no-op on non-Windows
** machines.  On Windows, static functions are defined that implement
** those standard interfaces.
*/
#if defined(_WIN32) && defined(_MSC_VER) && !defined(DBSQL_WINDIRENT_H)
#define DBSQL_WINDIRENT_H

#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#include <windows.h>
#include <io.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <string.h>
#ifndef FILENAME_MAX
# define FILENAME_MAX (260)
#endif
#ifndef S_ISREG
#define S_ISREG(m) (((m) & S_IFMT) == S_IFREG)
#endif
#ifndef S_ISDIR
#define S_ISDIR(m) (((m) & S_IFMT) == S_IFDIR)
#endif
#ifndef S_ISLNK
#define S_ISLNK(m) (0)
#endif
typedef unsigned short mode_t;

/* The dirent object for Windows is abbreviated.  The only field really
** usable by applications is d_name[].
*/
struct dirent {
 int d_ino;                  /* Inode number (synthesized) */
 unsigned d_attributes;      /* File attributes */
 char d_name[FILENAME_MAX];  /* Null-terminated filename */
};

/* The internals of DIR are opaque according to standards.  So it
** does not matter what we put here. */
typedef struct DIR DIR;
struct DIR {
  intptr_t d_handle;         /* Handle for findfirst()/findnext() */
  struct dirent cur;         /* Current entry */
};

/* Ignore hidden and system files */
#define WINDOWS_FILE_TO_IGNORE(a) \
    ((((a).attrib)&_A_HIDDEN) || (((a).attrib)&_A_SYSTEM))

/*
** Close a previously opened directory
*/
static int closedir(DIR *dir){
  int rc = 0;
  if( dir==0 ){
    return EINVAL;
  }
  if( dir->d_handle!=0 && dir->d_handle!=(-1) ){
    rc = _findclose(dir->d_handle);
  }
  dbsql_free(dir);
  return rc;
}

/*
** Open a new directory.  The directory name should be UTF-8 encoded.
** appropriate translations happen automatically.
*/
static DIR *opendir(const char *dir_name){
  DIR *dir;
  wchar_t *b1;
  int64_t sz;
  struct _wfinddata_t data;

  dir = dbsql_malloc64( sizeof(DIR) );
  if( dir==0 ) return 0;
  memset(dir, 0, sizeof(DIR));
  memset(&data, 0, sizeof(data));
  sz = strlen(dir_name);
  b1 = dbsql_malloc64( (sz+3)*sizeof(b1[0]) );
  if( b1==0 ){
    closedir(dir);
    return NULL;
  }
  sz = __multi_byte_to_wide_char(CP_UTF8, 0, dir_name, sz, b1, sz);
  b1[sz++] = '\\';
  b1[sz++] = '*';
  b1[sz] = 0;
  if( sz+1>sizeof(data.name)/sizeof(data.name[0]) ){
    closedir(dir);
    dbsql_free(b1);
    return NULL;
  }
  memcpy(data.name, b1, (sz+1)*sizeof(b1[0]));
  dbsql_free(b1);
  dir->d_handle = _wfindfirst(data.name, &data);
  if( dir->d_handle<0 ){
    closedir(dir);
    return NULL;
  }
  while( WINDOWS_FILE_TO_IGNORE(data) ){
    memset(&data, 0, sizeof(data));
    if( _wfindnext(dir->d_handle, &data)==-1 ){
      closedir(dir);
      return NULL;
    }
  }
  dir->cur.d_ino = 0;
  dir->cur.d_attributes = data.attrib;
  __wide_char_to_multi_byte(CP_UTF8, 0, data.name, -1,
                      dir->cur.d_name, FILENAME_MAX, 0, 0);
  return dir;
}

/*
** Read the next entry from a directory.
**
** The returned struct-dirent object is managed by DIR.  It is only
** valid until the next readdir() or closedir() call.  Only the
** d_name[] field is meaningful.  The d_name[] value has been
** translated into UTF8.
*/
static struct dirent *readdir(DIR *dir){
  struct _wfinddata_t data;
  if( dir==0 ) return 0;
  if( (dir->cur.d_ino++)==0 ){
    return &dir->cur;
  }
  do{
    memset(&data, 0, sizeof(data));
    if( _wfindnext(dir->d_handle, &data)==-1 ){
      return NULL;
    }
  }while( WINDOWS_FILE_TO_IGNORE(data) );
  dir->cur.d_attributes = data.attrib;
  __wide_char_to_multi_byte(CP_UTF8, 0, data.name, -1,
                      dir->cur.d_name, FILENAME_MAX, 0, 0);
  return &dir->cur;
}

#endif /* defined(_WIN32) && defined(_MSC_VER) */

