/*
** 2019-01-21
**
** The author disclaims copyright to this source code.  In place of
** a legal notice, here is a blessing:
**
**    May you do good and not evil.
**    May you find forgiveness for yourself and forgive others.
**    May you share freely, never taking more than you give.
**
*************************************************************************
**
** This file implements an extension that uses the DBSQL_CONFIG_MALLOC
** mechanism to add a tracing layer on top of dbsql.  If this extension
** is registered prior to dbsql_initialize(), it will cause all memory
** allocation activities to be logged on standard output, or to some other
** FILE specified by the initializer.
**
** This file needs to be compiled into the application that uses it.
**
** This extension is used to implement the --memtrace option of the
** command-line shell.
*/
#include <assert.h>
#include <string.h>
#include <stdio.h>

/* The original memory allocation routines */
static dbsql_mem_methods_t __memtrace_base;
static FILE *__memtrace_out;

/* Methods that trace memory allocations */
static void *__memtrace_malloc(int n){
  if( __memtrace_out ){
    fprintf(__memtrace_out, "MEMTRACE: allocate %d bytes\n", 
            __memtrace_base.roundup(n));
  }
  return __memtrace_base.x_malloc(n);
}
static void __memtrace_free(void *p){
  if( p==0 ) return;
  if( __memtrace_out ){
    fprintf(__memtrace_out, "MEMTRACE: free %d bytes\n", __memtrace_base.size(p));
  }
  __memtrace_base.__x_free(p);
}
static void *__memtrace_realloc(void *p, int n){
  if( p==0 ) return __memtrace_malloc(n);
  if( n==0 ){
    __memtrace_free(p);
    return 0;
  }
  if( __memtrace_out ){
    fprintf(__memtrace_out, "MEMTRACE: resize %d -> %d bytes\n",
            __memtrace_base.size(p), __memtrace_base.roundup(n));
  }
  return __memtrace_base.x_realloc(p, n);
}
static int __memtrace_size(void *p){
  return __memtrace_base.size(p);
}
static int __memtrace_roundup(int n){
  return __memtrace_base.roundup(n);
}
static int __memtrace_init(void *p){
  return __memtrace_base.init(p);
}
static void __memtrace_shutdown(void *p){
  __memtrace_base.shutdown(p);
}

/* The substitute memory allocator */
static dbsql_mem_methods_t __ersazt_methods = {
  __memtrace_malloc,
  __memtrace_free,
  __memtrace_realloc,
  __memtrace_size,
  __memtrace_roundup,
  __memtrace_init,
  __memtrace_shutdown,
  0
};

/* Begin tracing memory allocations to out. */
int __mem_trace_activate(FILE *out){
  int rc = DBSQL_OK;
  if( __memtrace_base.x_malloc==0 ){
    rc = dbsql_config(DBSQL_CONFIG_GETMALLOC, &__memtrace_base);
    if( rc==DBSQL_OK ){
      rc = dbsql_config(DBSQL_CONFIG_MALLOC, &__ersazt_methods);
    }
  }
  __memtrace_out = out;
  return rc;
}

/* Deactivate memory tracing */
int __mem_trace_deactivate(void){
  int rc = DBSQL_OK;
  if( __memtrace_base.x_malloc!=0 ){
    rc = dbsql_config(DBSQL_CONFIG_MALLOC, &__memtrace_base);
    if( rc==DBSQL_OK ){
      memset(&__memtrace_base, 0, sizeof(__memtrace_base));
    }
  }
  __memtrace_out = 0;
  return rc;
}

/************************* End ext/misc/memtrace.c ********************/
