/*
** 2023-06-21
**
** The author disclaims copyright to this source code.  In place of
** a legal notice, here is a blessing:
**
**    May you do good and not evil.
**    May you find forgiveness for yourself and forgive others.
**    May you share freely, never taking more than you give.
**
*************************************************************************
**
** This file implements an extension that uses the DBSQL_CONFIG_PCACHE2
** mechanism to add a tracing layer on top of pluggable page cache of
** dbsql.  If this extension is registered prior to dbsql_initialize(),
** it will cause all page cache activities to be logged on standard output,
** or to some other FILE specified by the initializer.
**
** This file needs to be compiled into the application that uses it.
**
** This extension is used to implement the --pcachetrace option of the
** command-line shell.
*/
#include <assert.h>
#include <string.h>
#include <stdio.h>

/* The original page cache routines */
static dbsql_pcache_methods2_t __pcache_base;
static FILE *__pcachetrace_out;

/* Methods that trace pcache activity */
static int __pcachetrace_init(void *arg){
  int n_res;
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xInit(%p)\n", arg);
  }
  n_res = __pcache_base.init(arg);
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xInit(%p) -> %d\n", arg, n_res);
  }
  return n_res;
}
static void __pcachetrace_shutdown(void *arg){
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xShutdown(%p)\n", arg);
  }
  __pcache_base.shutdown(arg);
}
static dbsql_pcache_t *__pcachetrace_create(int sz_page, int sz_extra, int purge){
  dbsql_pcache_t *res;
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xCreate(%d,%d,%d)\n",
            sz_page, sz_extra, purge);
  }
  res = __pcache_base.create(sz_page, sz_extra, purge);
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xCreate(%d,%d,%d) -> %p\n",
            sz_page, sz_extra, purge, res);
  }
  return res;
}
static void __pcachetrace_cachesize(dbsql_pcache_t *p, int n_cachesize){
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xCachesize(%p, %d)\n", p, n_cachesize);
  }
  __pcache_base.cachesize(p, n_cachesize);
}
static int __pcachetrace_pagecount(dbsql_pcache_t *p){
  int n_res;
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xPagecount(%p)\n", p);
  }
  n_res = __pcache_base.pagecount(p);
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xPagecount(%p) -> %d\n", p, n_res);
  }
  return n_res;
}
static dbsql_pcache_page_t *__pcachetrace_fetch(
  dbsql_pcache_t *p,
  unsigned key,
  int cr_fg
){
  dbsql_pcache_page_t *res;
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xFetch(%p,%u,%d)\n", p, key, cr_fg);
  }
  res = __pcache_base.fetch(p, key, cr_fg);
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xFetch(%p,%u,%d) -> %p\n",
            p, key, cr_fg, res);
  }
  return res;
}
static void __pcachetrace_unpin(
  dbsql_pcache_t *p,
  dbsql_pcache_page_t *pg,
  int discard
){
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xUnpin(%p, %p, %d)\n",
            p, pg, discard);
  }
  __pcache_base.unpin(p, pg, discard);
}
static void __pcachetrace_rekey(
  dbsql_pcache_t *p,
  dbsql_pcache_page_t *pg,
  unsigned old_key,
  unsigned new_key
){
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xRekey(%p, %p, %u, %u)\n",
        p, pg, old_key, new_key);
  }
  __pcache_base.rekey(p, pg, old_key, new_key);
}
static void __pcachetrace_truncate(dbsql_pcache_t *p, unsigned n){
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xTruncate(%p, %u)\n", p, n);
  }
  __pcache_base.truncate(p, n);
}
static void __pcachetrace_destroy(dbsql_pcache_t *p){
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xDestroy(%p)\n", p);
  }
  __pcache_base.destroy(p);
}
static void __pcachetrace_shrink(dbsql_pcache_t *p){
  if( __pcachetrace_out ){
    fprintf(__pcachetrace_out, "PCACHETRACE: xShrink(%p)\n", p);
  }
  __pcache_base.shrink(p);
}

/* The substitute pcache methods */
static dbsql_pcache_methods2_t __ersazt_pcache_methods = {
  0,
  0,
  __pcachetrace_init,
  __pcachetrace_shutdown,
  __pcachetrace_create,
  __pcachetrace_cachesize,
  __pcachetrace_pagecount,
  __pcachetrace_fetch,
  __pcachetrace_unpin,
  __pcachetrace_rekey,
  __pcachetrace_truncate,
  __pcachetrace_destroy,
  __pcachetrace_shrink
};

/* Begin tracing memory allocations to out. */
int __pcache_trace_activate(FILE *out){
  int rc = DBSQL_OK;
  if( __pcache_base.fetch==0 ){
    rc = dbsql_config(DBSQL_CONFIG_GETPCACHE2, &__pcache_base);
    if( rc==DBSQL_OK ){
      rc = dbsql_config(DBSQL_CONFIG_PCACHE2, &__ersazt_pcache_methods);
    }
  }
  __pcachetrace_out = out;
  return rc;
}

/* Deactivate memory tracing */
int __pcache_trace_deactivate(void){
  int rc = DBSQL_OK;
  if( __pcache_base.fetch!=0 ){
    rc = dbsql_config(DBSQL_CONFIG_PCACHE2, &__pcache_base);
    if( rc==DBSQL_OK ){
      memset(&__pcache_base, 0, sizeof(__pcache_base));
    }
  }
  __pcachetrace_out = 0;
  return rc;
}

