static int __vfstrace_file_size(dbsql_file_t*, int64_t *size);
static int __vfstrace_lock(dbsql_file_t*, int);
static int __vfstrace_unlock(dbsql_file_t*, int);
static int __vfstrace_check_reserved_lock(dbsql_file_t*, int *);
static int __vfstrace_file_control(dbsql_file_t*, int op, void *arg);
static int __vfstrace_sector_size(dbsql_file_t*);
static int __vfstrace_device_characteristics(dbsql_file_t*);
static int __vfstrace_shm_lock(dbsql_file_t*,int,int,int);
static int __vfstrace_shm_map(dbsql_file_t*,int,int,int, void volatile **);
