static const char *__vfstrace_next_system_call(dbsql_vfs_t*, const char *name);

/*
** Return a pointer to the tail of the pathname.  Examples:
**
**     /home/drh/xyzzy.txt -> xyzzy.txt
**     xyzzy.txt           -> xyzzy.txt
*/
static const char *__file_tail(const char *z){
  size_t i;
  if( z==0 ) return 0;
  i = strlen(z)-1;
  while( i>0 && z[i-1]!='/' ){ i--; }
  return &z[i];
}

/*
** Send trace output defined by format and subsequent arguments.
*/
static void vfstrace_printf(
  vfstrace_info *info,
  const char *format,
  ...
){
  va_list ap;
  char *msg;
  if( info->on ){
    va_start(ap, format);
    msg = dbsql_vmprintf(format, ap);
    va_end(ap);
    info->out(msg, info->out_arg);
    dbsql_free(msg);
  }
}

/*
** Try to convert an error code into a symbolic name for that error code.
*/
static const char *vfstrace_errcode_name(int rc ){
  const char *val = 0;
  switch( rc ){
    case DBSQL_OK:                 val = "DBSQL_OK";                 break;
    case DBSQL_INTERNAL:           val = "DBSQL_INTERNAL";           break;
    case DBSQL_ERROR:              val = "DBSQL_ERROR";              break;
    case DBSQL_PERM:               val = "DBSQL_PERM";               break;
    case DBSQL_ABORT:              val = "DBSQL_ABORT";              break;
    case DBSQL_BUSY:               val = "DBSQL_BUSY";               break;
    case DBSQL_LOCKED:             val = "DBSQL_LOCKED";             break;
    case DBSQL_NOMEM:              val = "DBSQL_NOMEM";              break;
    case DBSQL_READONLY:           val = "DBSQL_READONLY";           break;
    case DBSQL_INTERRUPT:          val = "DBSQL_INTERRUPT";          break;
    case DBSQL_IOERR:              val = "DBSQL_IOERR";              break;
    case DBSQL_CORRUPT:            val = "DBSQL_CORRUPT";            break;
    case DBSQL_NOTFOUND:           val = "DBSQL_NOTFOUND";           break;
    case DBSQL_FULL:               val = "DBSQL_FULL";               break;
    case DBSQL_CANTOPEN:           val = "DBSQL_CANTOPEN";           break;
    case DBSQL_PROTOCOL:           val = "DBSQL_PROTOCOL";           break;
    case DBSQL_EMPTY:              val = "DBSQL_EMPTY";              break;
    case DBSQL_SCHEMA:             val = "DBSQL_SCHEMA";             break;
    case DBSQL_TOOBIG:             val = "DBSQL_TOOBIG";             break;
    case DBSQL_CONSTRAINT:         val = "DBSQL_CONSTRAINT";         break;
    case DBSQL_MISMATCH:           val = "DBSQL_MISMATCH";           break;
    case DBSQL_MISUSE:             val = "DBSQL_MISUSE";             break;
    case DBSQL_NOLFS:              val = "DBSQL_NOLFS";              break;
    case DBSQL_IOERR_READ:         val = "DBSQL_IOERR_READ";         break;
    case DBSQL_IOERR_SHORT_READ:   val = "DBSQL_IOERR_SHORT_READ";   break;
    case DBSQL_IOERR_WRITE:        val = "DBSQL_IOERR_WRITE";        break;
    case DBSQL_IOERR_FSYNC:        val = "DBSQL_IOERR_FSYNC";        break;
    case DBSQL_IOERR_DIR_FSYNC:    val = "DBSQL_IOERR_DIR_FSYNC";    break;
    case DBSQL_IOERR_TRUNCATE:     val = "DBSQL_IOERR_TRUNCATE";     break;
    case DBSQL_IOERR_FSTAT:        val = "DBSQL_IOERR_FSTAT";        break;
    case DBSQL_IOERR_UNLOCK:       val = "DBSQL_IOERR_UNLOCK";       break;
    case DBSQL_IOERR_RDLOCK:       val = "DBSQL_IOERR_RDLOCK";       break;
    case DBSQL_IOERR_DELETE:       val = "DBSQL_IOERR_DELETE";       break;
    case DBSQL_IOERR_BLOCKED:      val = "DBSQL_IOERR_BLOCKED";      break;
    case DBSQL_IOERR_NOMEM:        val = "DBSQL_IOERR_NOMEM";        break;
    case DBSQL_IOERR_ACCESS:       val = "DBSQL_IOERR_ACCESS";       break;
    case DBSQL_IOERR_CHECKRESERVEDLOCK:
                               val = "DBSQL_IOERR_CHECKRESERVEDLOCK"; break;
    case DBSQL_IOERR_LOCK:         val = "DBSQL_IOERR_LOCK";         break;
    case DBSQL_IOERR_CLOSE:        val = "DBSQL_IOERR_CLOSE";        break;
    case DBSQL_IOERR_DIR_CLOSE:    val = "DBSQL_IOERR_DIR_CLOSE";    break;
    case DBSQL_IOERR_SHMOPEN:      val = "DBSQL_IOERR_SHMOPEN";      break;
    case DBSQL_IOERR_SHMSIZE:      val = "DBSQL_IOERR_SHMSIZE";      break;
    case DBSQL_IOERR_SHMLOCK:      val = "DBSQL_IOERR_SHMLOCK";      break;
    case DBSQL_IOERR_SHMMAP:       val = "DBSQL_IOERR_SHMMAP";       break;
    case DBSQL_IOERR_SEEK:         val = "DBSQL_IOERR_SEEK";         break;
    case DBSQL_IOERR_GETTEMPPATH:  val = "DBSQL_IOERR_GETTEMPPATH";  break;
    case DBSQL_IOERR_CONVPATH:     val = "DBSQL_IOERR_CONVPATH";     break;
    case DBSQL_READONLY_DBMOVED:   val = "DBSQL_READONLY_DBMOVED";   break;
    case DBSQL_LOCKED_SHAREDCACHE: val = "DBSQL_LOCKED_SHAREDCACHE"; break;
    case DBSQL_BUSY_RECOVERY:      val = "DBSQL_BUSY_RECOVERY";      break;
    case DBSQL_CANTOPEN_NOTEMPDIR: val = "DBSQL_CANTOPEN_NOTEMPDIR"; break;
  }
  return val;
}

/*
** Convert value rc into a string and print it using format.  format
** should have exactly one %s
*/
static void vfstrace_print_errcode(
  vfstrace_info *info,
  const char *format,
  int rc
){
  const char *val;
  char buf[50];
  val = vfstrace_errcode_name(rc);
  if( val==0 ){
    val = vfstrace_errcode_name(rc&0xff);
    if( val ){
      dbsql_snprintf(sizeof(buf), buf, "%s | 0x%x", val, rc&0xffff00);
    }else{
      dbsql_snprintf(sizeof(buf), buf, "%d (0x%x)", rc, rc);
    }
    val = buf;
  }
  vfstrace_printf(info, format, val);
}

/*
** Append to a buffer.
*/
static void strappend(char *z, int *p_i, const char *append){
  int i = *p_i;
  while( append[0] ){ z[i++] = *(append++); }
  z[i] = 0;
  *p_i = i;
}

/*
** Turn tracing output on or off according to m_mask.
*/
static void __vfstrace_on_off(vfstrace_info *info, unsigned int m_mask){
  info->on = (info->m_trace & m_mask)!=0;
}

/*
** Close an vfstrace-file.
*/
static int __vfstrace_close(dbsql_file_t *file){
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  __vfstrace_on_off(info, VTR_CLOSE);
  vfstrace_printf(info, "%s.xClose(%s)", info->vfs_name, p->f_name);
  rc = p->real->methods->x_close(p->real);
  vfstrace_print_errcode(info, " -> %s\n", rc);
  if( rc==DBSQL_OK ){
    dbsql_free((void*)p->base.methods);
    p->base.methods = 0;
  }
  return rc;
}

/*
** Read data from an vfstrace-file.
*/
static int __vfstrace_read(
  dbsql_file_t *file, 
  void *buf, 
  int i_amt, 
  int64_t i_ofst
){
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  __vfstrace_on_off(info, VTR_READ);
  vfstrace_printf(info, "%s.xRead(%s,n=%d,ofst=%lld)",
                  info->vfs_name, p->f_name, i_amt, i_ofst);
  rc = p->real->methods->x_read(p->real, buf, i_amt, i_ofst);
  vfstrace_print_errcode(info, " -> %s\n", rc);
  return rc;
}

/*
** Write data to an vfstrace-file.
*/
static int __vfstrace_write(
  dbsql_file_t *file, 
  const void *buf, 
  int i_amt, 
  int64_t i_ofst
){
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  __vfstrace_on_off(info, VTR_WRITE);
  vfstrace_printf(info, "%s.xWrite(%s,n=%d,ofst=%lld)",
                  info->vfs_name, p->f_name, i_amt, i_ofst);
  rc = p->real->methods->x_write(p->real, buf, i_amt, i_ofst);
  vfstrace_print_errcode(info, " -> %s\n", rc);
  return rc;
}

/*
** Truncate an vfstrace-file.
*/
static int __vfstrace_truncate(dbsql_file_t *file, int64_t size){
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  __vfstrace_on_off(info, VTR_TRUNC);
  vfstrace_printf(info, "%s.xTruncate(%s,%lld)", info->vfs_name, p->f_name,
                  size);
  rc = p->real->methods->truncate(p->real, size);
  vfstrace_printf(info, " -> %d\n", rc);
  return rc;
}

/*
** Sync an vfstrace-file.
*/
static int __vfstrace_sync(dbsql_file_t *file, int flags){
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  int i;
  char buf[100];
  memcpy(buf, "|0", 3);
  i = 0;
  if( flags & DBSQL_SYNC_FULL )        strappend(buf, &i, "|FULL");
  else if( flags & DBSQL_SYNC_NORMAL ) strappend(buf, &i, "|NORMAL");
  if( flags & DBSQL_SYNC_DATAONLY )    strappend(buf, &i, "|DATAONLY");
  if( flags & ~(DBSQL_SYNC_FULL|DBSQL_SYNC_DATAONLY) ){
    dbsql_snprintf(sizeof(buf)-i, &buf[i], "|0x%x", flags);
  }
  __vfstrace_on_off(info, VTR_SYNC);
  vfstrace_printf(info, "%s.xSync(%s,%s)", info->vfs_name, p->f_name,
                  &buf[1]);
  rc = p->real->methods->x_sync(p->real, flags);
  vfstrace_printf(info, " -> %d\n", rc);
  return rc;
}

/*
** Return the current file-size of an vfstrace-file.
*/
static int __vfstrace_file_size(dbsql_file_t *file, int64_t *size){
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  __vfstrace_on_off(info, VTR_FSIZE);
  vfstrace_printf(info, "%s.xFileSize(%s)", info->vfs_name, p->f_name);
  rc = p->real->methods->file_size(p->real, size);
  vfstrace_print_errcode(info, " -> %s,", rc);
  vfstrace_printf(info, " size=%lld\n", *size);
  return rc;
}

/*
** Return the name of a lock.
*/
static const char *__lock_name(int lock){
  const char *lock_names[] = {
     "NONE", "SHARED", "RESERVED", "PENDING", "EXCLUSIVE"
  };
  if( lock<0 || lock>=(int)(sizeof(lock_names)/sizeof(lock_names[0])) ){
    return "???";
  }else{
    return lock_names[lock];
  }
}

/*
** Lock an vfstrace-file.
*/
static int __vfstrace_lock(dbsql_file_t *file, int lock){
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  __vfstrace_on_off(info, VTR_LOCK);
  vfstrace_printf(info, "%s.xLock(%s,%s)", info->vfs_name, p->f_name,
                  __lock_name(lock));
  rc = p->real->methods->lock(p->real, lock);
  vfstrace_print_errcode(info, " -> %s\n", rc);
  return rc;
}

/*
** Unlock an vfstrace-file.
*/
static int __vfstrace_unlock(dbsql_file_t *file, int lock){
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  __vfstrace_on_off(info, VTR_UNLOCK);
  vfstrace_printf(info, "%s.xUnlock(%s,%s)", info->vfs_name, p->f_name,
                  __lock_name(lock));
  rc = p->real->methods->unlock(p->real, lock);
  vfstrace_print_errcode(info, " -> %s\n", rc);
  return rc;
}

/*
** Check if another file-handle holds a RESERVED lock on an vfstrace-file.
*/
static int __vfstrace_check_reserved_lock(dbsql_file_t *file, int *res_out){
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  __vfstrace_on_off(info, VTR_CRL);
  vfstrace_printf(info, "%s.xCheckReservedLock(%s,%d)", 
                  info->vfs_name, p->f_name);
  rc = p->real->methods->check_reserved_lock(p->real, res_out);
  vfstrace_print_errcode(info, " -> %s", rc);
  vfstrace_printf(info, ", out=%d\n", *res_out);
  return rc;
}

/*
** File control method. For custom operations on an vfstrace-file.
*/
static int __vfstrace_file_control(dbsql_file_t *file, int op, void *arg){
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  char buf[100];
  char buf2[100];
  char *z_op;
  char *r_val = 0;
  __vfstrace_on_off(info, VTR_FCTRL);
  switch( op ){
    case DBSQL_FCNTL_LOCKSTATE:           z_op = "LOCKSTATE";           break;
    case DBSQL_GET_LOCKPROXYFILE:         z_op = "GET_LOCKPROXYFILE";   break;
    case DBSQL_SET_LOCKPROXYFILE:         z_op = "SET_LOCKPROXYFILE";   break;
    case DBSQL_LAST_ERRNO:                z_op = "LAST_ERRNO";          break;
    case DBSQL_FCNTL_SIZE_HINT: {
      dbsql_snprintf(sizeof(buf), buf, "SIZE_HINT,%lld",
                       *(int64_t*)arg);
      z_op = buf;
      break;
    }
    case DBSQL_FCNTL_CHUNK_SIZE: {
      dbsql_snprintf(sizeof(buf), buf, "CHUNK_SIZE,%d", *(int*)arg);
      z_op = buf;
      break;
    }
    case DBSQL_FCNTL_FILE_POINTER:        z_op = "FILE_POINTER";        break;
    case DBSQL_FCNTL_WIN32_AV_RETRY:      z_op = "WIN32_AV_RETRY";      break;
    case DBSQL_FCNTL_PERSIST_WAL: {
       dbsql_snprintf(sizeof(buf), buf, "PERSIST_WAL,%d", *(int*)arg);
       z_op = buf;
       break;
    }
    case DBSQL_FCNTL_OVERWRITE:           z_op = "OVERWRITE";           break;
    case DBSQL_FCNTL_VFSNAME:             z_op = "VFSNAME";             break;
    case DBSQL_FCNTL_POWERSAFE_OVERWRITE: z_op = "POWERSAFE_OVERWRITE"; break;
    case DBSQL_FCNTL_PRAGMA: {
      const char *const* a = (const char*const*)arg;
      if( a[1] && strcmp(a[1],"vfstrace")==0 && a[2] ){
        const u_int8_t *z_arg = (const u_int8_t*)a[2];
        if( z_arg[0]>='0' && z_arg[0]<='9' ){
          info->m_trace = (u_int64_t)strtoll(a[2], 0, 0);
        }else{
          static const struct {
            const char *z;
            unsigned int m;
          } kws[] = {
            { "all",                   0xffffffff   },
            { "close",                 VTR_CLOSE    },
            { "read",                  VTR_READ     },
            { "write",                 VTR_WRITE    },
            { "truncate",              VTR_TRUNC    },
            { "sync",                  VTR_SYNC     },
            { "filesize",              VTR_FSIZE    },
            { "lock",                  VTR_LOCK     },
            { "unlock",                VTR_UNLOCK   },
            { "checkreservedlock",     VTR_CRL      },
            { "filecontrol",           VTR_FCTRL    },
            { "sectorsize",            VTR_SECSZ    },
            { "devicecharacteristics", VTR_DEVCHAR  },
            { "shmlock",               VTR_SHMLOCK  },
            { "shmmap",                VTR_SHMMAP   },
            { "shmummap",              VTR_SHMUNMAP },
            { "shmbarrier",            VTR_SHMBAR   },
            { "open",                  VTR_OPEN     },
            { "delete",                VTR_DELETE   },
            { "access",                VTR_ACCESS   },
            { "fullpathname",          VTR_FULLPATH },
            { "dlopen",                VTR_DLOPEN   },
            { "dlerror",               VTR_DLERR    },
            { "dlsym",                 VTR_DLSYM    },
            { "dlclose",               VTR_DLCLOSE  },
            { "randomness",            VTR_RAND     },
            { "sleep",                 VTR_SLEEP    },
            { "currenttime",           VTR_CURTIME  },
            { "currenttimeint64",      VTR_CURTIME  },
            { "getlasterror",          VTR_LASTERR  },
            { "fetch",                 VTR_FETCH    },
          };
          int on_off = 1;
          while( z_arg[0] ){
            int jj, n;
            while( z_arg[0]!=0 && z_arg[0]!='-' && z_arg[0]!='+'
                   && !isalpha(z_arg[0]) ) z_arg++;
            if( z_arg[0]==0 ) break;
            if( z_arg[0]=='-' ){
              on_off = 0;
              z_arg++;
            }else if( z_arg[0]=='+' ){
              on_off = 1;
              z_arg++;
            }
            while( !isalpha(z_arg[0]) ){
              if( z_arg[0]==0 ) break;
              z_arg++;
            }
            if( z_arg[0]=='x' && isalpha(z_arg[1]) ) z_arg++;
            for(n=0; isalpha(z_arg[n]); n++){}
            for(jj=0; jj<(int)(sizeof(kws)/sizeof(kws[0])); jj++){
              if( dbsql_strnicmp(kws[jj].z,(const char*)z_arg,n)==0 ){
                if( on_off ){
                  info->m_trace |= kws[jj].m;
                }else{
                  info->m_trace &= ~kws[jj].m;
                }
                break;
              }
            }
            z_arg += n;
          }
        }
      }
      dbsql_snprintf(sizeof(buf), buf, "PRAGMA,[%s,%s]",a[1],a[2]);
      z_op = buf;
      break;
    }
    case DBSQL_FCNTL_BUSYHANDLER:         z_op = "BUSYHANDLER";         break;
    case DBSQL_FCNTL_TEMPFILENAME:        z_op = "TEMPFILENAME";        break;
    case DBSQL_FCNTL_MMAP_SIZE: {
      int64_t i_m_map = *(int64_t*)arg;
      dbsql_snprintf(sizeof(buf), buf, "MMAP_SIZE,%lld",i_m_map);
      z_op = buf;
      break;
    }
    case DBSQL_FCNTL_TRACE:               z_op = "TRACE";               break;
    case DBSQL_FCNTL_HAS_MOVED:           z_op = "HAS_MOVED";           break;
    case DBSQL_FCNTL_SYNC:                z_op = "SYNC";                break;
    case DBSQL_FCNTL_COMMIT_PHASETWO:     z_op = "COMMIT_PHASETWO";     break;
    case DBSQL_FCNTL_WIN32_SET_HANDLE:    z_op = "WIN32_SET_HANDLE";    break;
    case DBSQL_FCNTL_WAL_BLOCK:           z_op = "WAL_BLOCK";           break;
    case DBSQL_FCNTL_ZIPVFS:              z_op = "ZIPVFS";              break; 
    case DBSQL_FCNTL_RBU:                 z_op = "RBU";                 break;
    case DBSQL_FCNTL_VFS_POINTER:         z_op = "VFS_POINTER";         break;
    case DBSQL_FCNTL_JOURNAL_POINTER:     z_op = "JOURNAL_POINTER";     break;
    case DBSQL_FCNTL_WIN32_GET_HANDLE:    z_op = "WIN32_GET_HANDLE";    break;
    case DBSQL_FCNTL_PDB:                 z_op = "PDB";                 break;
    case DBSQL_FCNTL_BEGIN_ATOMIC_WRITE:  z_op = "BEGIN_ATOMIC_WRITE";  break;
    case DBSQL_FCNTL_COMMIT_ATOMIC_WRITE: z_op = "COMMIT_ATOMIC_WRITE"; break;
    case DBSQL_FCNTL_ROLLBACK_ATOMIC_WRITE: {
       z_op = "ROLLBACK_ATOMIC_WRITE";
       break;
    }
    case DBSQL_FCNTL_LOCK_TIMEOUT: {
       dbsql_snprintf(sizeof(buf), buf, "LOCK_TIMEOUT,%d", *(int*)arg);
       z_op = buf;
       break;
    }
    case DBSQL_FCNTL_DATA_VERSION:        z_op = "DATA_VERSION";        break;
    case DBSQL_FCNTL_SIZE_LIMIT:          z_op = "SIZE_LIMIT";          break;
    case DBSQL_FCNTL_CKPT_DONE:           z_op = "CKPT_DONE";           break;
    case DBSQL_FCNTL_RESERVE_BYTES:       z_op = "RESERVED_BYTES";      break;
    case DBSQL_FCNTL_CKPT_START:          z_op = "CKPT_START";          break;
    case DBSQL_FCNTL_EXTERNAL_READER:     z_op = "EXTERNAL_READER";     break;
    case DBSQL_FCNTL_CKSM_FILE:           z_op = "CKSM_FILE";           break;
    case DBSQL_FCNTL_RESET_CACHE:         z_op = "RESET_CACHE";         break;
    case 0xca093fa0:                       z_op = "DB_UNCHANGED";        break;
    default: {
      dbsql_snprintf(sizeof buf, buf, "%d", op);
      z_op = buf;
      break;
    }
  }
  vfstrace_printf(info, "%s.xFileControl(%s,%s)",
                  info->vfs_name, p->f_name, z_op);
  rc = p->real->methods->file_control(p->real, op, arg);
  if( rc==DBSQL_OK ){
    switch( op ){
      case DBSQL_FCNTL_VFSNAME: {
        *(char**)arg = dbsql_mprintf("vfstrace.%s/%z",
                                    info->vfs_name, *(char**)arg);
        r_val = *(char**)arg;
        break;
      }
      case DBSQL_FCNTL_MMAP_SIZE: {
        dbsql_snprintf(sizeof(buf2), buf2, "%lld", *(int64_t*)arg);
        r_val = buf2;
        break;
      }
      case DBSQL_FCNTL_HAS_MOVED:
      case DBSQL_FCNTL_PERSIST_WAL: {
        dbsql_snprintf(sizeof(buf2), buf2, "%d", *(int*)arg);
        r_val = buf2;
        break;
      }
      case DBSQL_FCNTL_PRAGMA:
      case DBSQL_FCNTL_TEMPFILENAME: {
        r_val = *(char**)arg;
        break;
      }
    }
  }
  if( r_val ){
    vfstrace_print_errcode(info, " -> %s", rc);
    vfstrace_printf(info, ", %s\n", r_val);
  }else{
    vfstrace_print_errcode(info, " -> %s\n", rc);
  }
  return rc;
}

