/*
** Shared-memory operations.
*/
static int __vfstrace_shm_lock(dbsql_file_t *file, int ofst, int n, int flags){
  static const char *lock_names[] = {
     "WRITE",
     "CKPT",
     "RECOVER",
     "READ0",
     "READ1",
     "READ2",
     "READ3",
     "READ4",
  };
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  char lck[100];
  int i = 0;
  __vfstrace_on_off(info, VTR_SHMLOCK);
  memcpy(lck, "|0", 3);
  if( flags & DBSQL_SHM_UNLOCK )    strappend(lck, &i, "|UNLOCK");
  if( flags & DBSQL_SHM_LOCK )      strappend(lck, &i, "|LOCK");
  if( flags & DBSQL_SHM_SHARED )    strappend(lck, &i, "|SHARED");
  if( flags & DBSQL_SHM_EXCLUSIVE ) strappend(lck, &i, "|EXCLUSIVE");
  if( flags & ~(0xf) ){
     dbsql_snprintf(sizeof(lck)-i, &lck[i], "|0x%x", flags);
  }
  if( ofst>=0 && ofst<(int)(sizeof(lock_names)/sizeof(lock_names[0])) ){
    vfstrace_printf(info, "%s.xShmLock(%s,ofst=%d(%s),n=%d,%s)",
                  info->vfs_name, p->f_name, ofst, lock_names[ofst],
                  n, &lck[1]);
  }else{
    vfstrace_printf(info, "%s.xShmLock(%s,ofst=5d,n=%d,%s)",
                  info->vfs_name, p->f_name, ofst,
                  n, &lck[1]);
  }
  rc = p->real->methods->shm_lock(p->real, ofst, n, flags);
  vfstrace_print_errcode(info, " -> %s\n", rc);
  return rc;
}
static int __vfstrace_shm_map(
  dbsql_file_t *file, 
  int i_region, 
  int sz_region, 
  int is_write, 
  void volatile **pp
){
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = p->info;
  int rc;
  __vfstrace_on_off(info, VTR_SHMMAP);
  vfstrace_printf(info, "%s.xShmMap(%s,iRegion=%d,szRegion=%d,isWrite=%d,*)",
                  info->vfs_name, p->f_name, i_region, sz_region, is_write);
  rc = p->real->methods->shm_map(p->real, i_region, sz_region, is_write, pp);
  vfstrace_print_errcode(info, " -> %s\n", rc);
  return rc;
}
