/*
** Open an vfstrace file handle.
*/
static int __vfstrace_open(
  dbsql_vfs_t *vfs,
  const char *name,
  dbsql_file_t *file,
  int flags,
  int *out_flags
){
  int rc;
  vfstrace_file *p = (vfstrace_file *)file;
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  p->info = info;
  p->f_name = name ? __file_tail(name) : "<temp>";
  p->real = (dbsql_file_t *)&p[1];
  rc = root->x_open(root, name, p->real, flags, out_flags);
  __vfstrace_on_off(info, VTR_OPEN);
  vfstrace_printf(info, "%s.xOpen(%s,flags=0x%x)",
                  info->vfs_name, p->f_name, flags);
  if( p->real->methods ){
    dbsql_io_methods_t *p_new = dbsql_malloc64( sizeof(*p_new) );
    const dbsql_io_methods_t *sub = p->real->methods;
    memset(p_new, 0, sizeof(*p_new));
    p_new->i_version = sub->i_version;
    p_new->x_close = __vfstrace_close;
    p_new->x_read = __vfstrace_read;
    p_new->x_write = __vfstrace_write;
    p_new->truncate = __vfstrace_truncate;
    p_new->x_sync = __vfstrace_sync;
    p_new->file_size = __vfstrace_file_size;
    p_new->lock = __vfstrace_lock;
    p_new->unlock = __vfstrace_unlock;
    p_new->check_reserved_lock = __vfstrace_check_reserved_lock;
    p_new->file_control = __vfstrace_file_control;
    p_new->sector_size = __vfstrace_sector_size;
    p_new->device_characteristics = __vfstrace_device_characteristics;
    if( p_new->i_version>=2 ){
      p_new->shm_map = sub->shm_map ? __vfstrace_shm_map : 0;
      p_new->shm_lock = sub->shm_lock ? __vfstrace_shm_lock : 0;
      p_new->shm_barrier = sub->shm_barrier ? __vfstrace_shm_barrier : 0;
      p_new->shm_unmap = sub->shm_unmap ? __vfstrace_shm_unmap : 0;
    }
    if( p_new->i_version>=3 ){
      p_new->fetch = sub->fetch ? __vfstrace_fetch : 0;
      p_new->unfetch = sub->unfetch ? __vfstrace_unfetch : 0;
    }
    file->methods = p_new;
  }
  vfstrace_print_errcode(info, " -> %s", rc);
  if( out_flags ){
    vfstrace_printf(info, ", outFlags=0x%x\n", *out_flags);
  }else{
    vfstrace_printf(info, "\n");
  }
  return rc;
}

/*
** Delete the file located at path. If the dir_sync argument is true,
** ensure the file-system modifications are synced to disk before
** returning.
*/
static int __vfstrace_delete(dbsql_vfs_t *vfs, const char *path, int dir_sync){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  int rc;
  __vfstrace_on_off(info, VTR_DELETE);
  vfstrace_printf(info, "%s.xDelete(\"%s\",%d)",
                  info->vfs_name, path, dir_sync);
  rc = root->x_delete(root, path, dir_sync);
  vfstrace_print_errcode(info, " -> %s\n", rc);
  return rc;
}

/*
** Test for access permissions. Return true if the requested permission
** is available, or false otherwise.
*/
static int __vfstrace_access(
  dbsql_vfs_t *vfs, 
  const char *path, 
  int flags, 
  int *res_out
){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  int rc;
  __vfstrace_on_off(info, VTR_ACCESS);
  vfstrace_printf(info, "%s.xAccess(\"%s\",%d)",
                  info->vfs_name, path, flags);
  rc = root->x_access(root, path, flags, res_out);
  vfstrace_print_errcode(info, " -> %s", rc);
  vfstrace_printf(info, ", out=%d\n", *res_out);
  return rc;
}

/*
** Populate buffer out with the full canonical pathname corresponding
** to the pathname in path. out is guaranteed to point to a buffer
** of at least (DEVSYM_MAX_PATHNAME+1) bytes.
*/
static int __vfstrace_full_pathname(
  dbsql_vfs_t *vfs, 
  const char *path, 
  int n_out, 
  char *out
){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  int rc;
  __vfstrace_on_off(info, VTR_FULLPATH);
  vfstrace_printf(info, "%s.xFullPathname(\"%s\")",
                  info->vfs_name, path);
  rc = root->full_pathname(root, path, n_out, out);
  vfstrace_print_errcode(info, " -> %s", rc);
  vfstrace_printf(info, ", out=\"%.*s\"\n", n_out, out);
  return rc;
}

/*
** Open the dynamic library located at path and return a handle.
*/
static void *__vfstrace_dl_open(dbsql_vfs_t *vfs, const char *path){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  __vfstrace_on_off(info, VTR_DLOPEN);
  vfstrace_printf(info, "%s.xDlOpen(\"%s\")\n", info->vfs_name, path);
  return root->dl_open(root, path);
}

/*
** Populate the buffer errmsg (size n_byte bytes) with a human readable
** utf-8 string describing the most recent error encountered associated 
** with dynamic libraries.
*/
static void __vfstrace_dl_error(dbsql_vfs_t *vfs, int n_byte, char *errmsg){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  __vfstrace_on_off(info, VTR_DLERR);
  vfstrace_printf(info, "%s.xDlError(%d)", info->vfs_name, n_byte);
  root->dl_error(root, n_byte, errmsg);
  vfstrace_printf(info, " -> \"%s\"", errmsg);
}

/*
** Return a pointer to the symbol symbol in the dynamic library handle.
*/
static void (*vfstrace_dl_sym(dbsql_vfs_t *vfs,void *p,const char *sym))(void){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  vfstrace_printf(info, "%s.xDlSym(\"%s\")\n", info->vfs_name, sym);
  return root->dl_sym(root, p, sym);
}

/*
** Close the dynamic library handle handle.
*/
static void __vfstrace_dl_close(dbsql_vfs_t *vfs, void *handle){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  __vfstrace_on_off(info, VTR_DLCLOSE);
  vfstrace_printf(info, "%s.xDlClose()\n", info->vfs_name);
  root->dl_close(root, handle);
}

/*
** Populate the buffer pointed to by buf_out with n_byte bytes of 
** random data.
*/
static int __vfstrace_randomness(dbsql_vfs_t *vfs, int n_byte, char *buf_out){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  __vfstrace_on_off(info, VTR_RAND);
  vfstrace_printf(info, "%s.xRandomness(%d)\n", info->vfs_name, n_byte);
  return root->randomness(root, n_byte, buf_out);
}

/*
** Sleep for n_micro microseconds. Return the number of microseconds 
** actually slept.
*/
static int __vfstrace_sleep(dbsql_vfs_t *vfs, int n_micro){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  __vfstrace_on_off(info, VTR_SLEEP);
  vfstrace_printf(info, "%s.xSleep(%d)\n", info->vfs_name, n_micro);
  return root->x_sleep(root, n_micro);
}

/*
** Return the current time as a Julian Day number in *time_out.
*/
static int __vfstrace_current_time(dbsql_vfs_t *vfs, double *time_out){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  int rc;
  __vfstrace_on_off(info, VTR_CURTIME);
  vfstrace_printf(info, "%s.xCurrentTime()", info->vfs_name);
  rc = root->current_time(root, time_out);
  vfstrace_printf(info, " -> %.17g\n", *time_out);
  return rc;
}
static int __vfstrace_current_time_int64(dbsql_vfs_t *vfs, int64_t *time_out){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  int rc;
  __vfstrace_on_off(info, VTR_CURTIME);
  vfstrace_printf(info, "%s.xCurrentTimeInt64()", info->vfs_name);
  rc = root->current_time_int64(root, time_out);
  vfstrace_printf(info, " -> %lld\n", *time_out);
  return rc;
}

/*
** Return the most recent error code and message
*/
static int __vfstrace_get_last_error(dbsql_vfs_t *vfs, int n_err, char *err){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  int rc;
  __vfstrace_on_off(info, VTR_LASTERR);
  vfstrace_printf(info, "%s.xGetLastError(%d,zBuf)", info->vfs_name, n_err);
  if( n_err ) err[0] = 0;
  rc = root->get_last_error(root, n_err, err);
  vfstrace_printf(info, " -> zBuf[] = \"%s\", rc = %d\n", n_err?err:"", rc);
  return rc;
}

/*
** Override system calls.
*/
static int __vfstrace_set_system_call(
  dbsql_vfs_t *vfs,
  const char *name,
  dbsql_syscall_ptr func
){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  return root->set_system_call(root, name, func);
}
static dbsql_syscall_ptr __vfstrace_get_system_call(
  dbsql_vfs_t *vfs,
  const char *name
){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  return root->get_system_call(root, name);
}
static const char *__vfstrace_next_system_call(dbsql_vfs_t *vfs, const char *name){
  vfstrace_info *info = (vfstrace_info*)vfs->app_data;
  dbsql_vfs_t *root = info->root_vfs;
  return root->next_system_call(root, name);
}


/*
** Clients invoke this routine to construct a new trace-vfs shim.
**
** Return DBSQL_OK on success.  
**
** DBSQL_NOMEM is returned in the case of a memory allocation error.
** DBSQL_NOTFOUND is returned if old_vfs_name does not exist.
*/
int vfstrace_register(
   const char *trace_name,           /* Name of the newly constructed VFS */
   const char *old_vfs_name,          /* Name of the underlying VFS */
   int (*out)(const char*,void*),   /* Output routine.  ex: fputs */
   void *out_arg,                    /* 2nd argument to out.  ex: stderr */
   int make_default                   /* True to make the new VFS the default */
){
  dbsql_vfs_t *p_new;
  dbsql_vfs_t *root;
  vfstrace_info *info;
  size_t n_name;
  size_t n_byte;

  root = dbsql_vfs_find(old_vfs_name);
  if( root==0 ) return DBSQL_NOTFOUND;
  n_name = strlen(trace_name);
  n_byte = sizeof(*p_new) + sizeof(*info) + n_name + 1;
  p_new = dbsql_malloc64( n_byte );
  if( p_new==0 ) return DBSQL_NOMEM;
  memset(p_new, 0, n_byte);
  info = (vfstrace_info*)&p_new[1];
  p_new->i_version = root->i_version;
  p_new->sz_os_file = root->sz_os_file + sizeof(vfstrace_file);
  p_new->mx_pathname = root->mx_pathname;
  p_new->name = (char*)&info[1];
  memcpy((char*)&info[1], trace_name, n_name+1);
  p_new->app_data = info;
  p_new->x_open = __vfstrace_open;
  p_new->x_delete = __vfstrace_delete;
  p_new->x_access = __vfstrace_access;
  p_new->full_pathname = __vfstrace_full_pathname;
  p_new->dl_open = root->dl_open==0 ? 0 : __vfstrace_dl_open;
  p_new->dl_error = root->dl_error==0 ? 0 : __vfstrace_dl_error;
  p_new->dl_sym = root->dl_sym==0 ? 0 : vfstrace_dl_sym;
  p_new->dl_close = root->dl_close==0 ? 0 : __vfstrace_dl_close;
  p_new->randomness = __vfstrace_randomness;
  p_new->x_sleep = __vfstrace_sleep;
  p_new->current_time = __vfstrace_current_time;
  p_new->get_last_error = root->get_last_error==0 ? 0 : __vfstrace_get_last_error;
  if( p_new->i_version>=2 ){
    p_new->current_time_int64 = root->current_time_int64==0 ? 0 :
                                   __vfstrace_current_time_int64;
    if( p_new->i_version>=3 ){
      p_new->set_system_call = root->set_system_call==0 ? 0 : 
                                   __vfstrace_set_system_call;
      p_new->get_system_call = root->get_system_call==0 ? 0 : 
                                   __vfstrace_get_system_call;
      p_new->next_system_call = root->next_system_call==0 ? 0 : 
                                   __vfstrace_next_system_call;
    }
  }
  info->root_vfs = root;
  info->out = out;
  info->out_arg = out_arg;
  info->vfs_name = p_new->name;
  info->trace_vfs = p_new;
  info->m_trace = 0xffffffff;
  info->on = 1;
  vfstrace_printf(info, "%s.enabled_for(\"%s\")\n",
       info->vfs_name, root->name);
  return dbsql_vfs_register(p_new, make_default);
}

/*
** Look for the named VFS.  If it is a TRACEVFS, then unregister it
** and delete it.
*/
void vfstrace_unregister(const char *trace_name){
  dbsql_vfs_t *vfs = dbsql_vfs_find(trace_name);
  if( vfs==0 ) return;
  if( vfs->x_open!=__vfstrace_open ) return;
  dbsql_vfs_unregister(vfs);
  dbsql_free(vfs);
}

